import org.apache.commons.lang.text.ExtendedMessageFormat;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

public class Scratch {
    public static void main(String[] a) throws Exception {
        test("it''s {0}", new Object[]{"done"});
        test("'{0}' literal {1}", new Object[]{"ignored", "done"});
        test("{0 upper}", null);
        test("no placeholders here", new Object[0]);
        test("{abc}", null);
        test("{0", null);
        test("it's unterminated {0}", null);
        test("{ 0 , upper }", new Object[]{"xyz"});
    }

    static void test(String pattern, Object[] args) {
        try {
            Map reg = new HashMap();
            reg.put("upper", new org.apache.commons.lang.text.FormatFactory() {
                public java.text.Format getFormat(String name, String arguments, Locale locale) {
                    if ("upper".equals(name)) {
                        return new java.text.Format() {
                            public StringBuffer format(Object obj, StringBuffer sb, java.text.FieldPosition fp) {
                                return sb.append(String.valueOf(obj).toUpperCase());
                            }
                            public Object parseObject(String s, java.text.ParsePosition p) {
                                p.setIndex(s.length());
                                return s;
                            }
                        };
                    }
                    return null;
                }
            });
            ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern, reg);
            String formatted = args != null ? emf.format(args) : null;
            System.out.println("pattern=[" + pattern + "] toPattern=[" + emf.toPattern() + "] format=[" + formatted + "]");
        } catch (Exception e) {
            System.out.println("pattern=[" + pattern + "] threw " + e.getClass().getName() + ": " + e.getMessage());
        }
    }
}
